<?php use SwimlogStandalone\WorkoutEntry as WE; ?>
<section class="calendar-panel workout-page" aria-labelledby="entry-title"><div class="workout-page-heading"><h2 id="entry-title">Import Workout</h2><a class="control" href="/?screen=log">Workout Log</a></div>
<?php if($entryError): ?><p role="alert"><?php echo esc_html($entryError->get_error_message()); ?></p><?php endif; ?>
<?php foreach($entryOutcomes as$out): ?><p class="<?php echo isset($out['error'])?'entry-error':'save-notice'; ?>" role="<?php echo isset($out['error'])?'alert':'status'; ?>"><?php echo esc_html($out['name'].': ');if(isset($out['error'])): echo esc_html($out['error']);elseif($out['pending']): echo 'Possible match preserved for review below.';else: echo $out['attached']?'Source attached to matching workout. ':'Workout imported. ';$w=\SwimLogEvaluation\Workout::get_for_user($out['workout_id'],$owner);if($w): ?><a href="<?php echo esc_url('/?workout='.$out['workout_id'].'&date='.substr($w->workout_start,0,10)); ?>">View workout</a><?php endif;endif; ?></p><?php endforeach; ?>
<form method="post" action="/?action=workout_upload" enctype="multipart/form-data" class="workout-upload">
<input type="hidden" name="token" value="<?php echo esc_attr($entryToken); ?>"><input type="hidden" name="nonce" value="<?php echo esc_attr(wp_create_nonce('standalone_entry_import_'.$entryToken)); ?>">
<div class="plan-field"><label for="workout-files">Workout files</label><input id="workout-files" type="file" name="workout_files[]" accept=".fit,.fit.gz,.zip,.csv,.csv.gz,.gpx,.gpx.gz,.tcx,.tcx.gz" required multiple><small>Up to 10 files. FIT, FIT.GZ, ZIP, FORM swim CSV, GPX and TCX, including gzip variants. ZIP must contain exactly one supported workout file. GPX/TCX are open-water tracks. The plugin permits 10 MB per uploaded and expanded file; your PHP limits also apply.</small><small><?php echo esc_html('Server limits: '.ini_get('upload_max_filesize').' per file; '.ini_get('post_max_size').' per request.'); ?></small></div>
<div class="plan-field"><label for="upload-location">Location</label><select id="upload-location" name="location_id"><option value="0">Use existing import location rules</option><?php foreach($entryLocations as$loc): ?><option value="<?php echo esc_attr($loc['id']); ?>"><?php echo esc_html($loc['name']); ?></option><?php endforeach; ?></select></div><button>Upload and import</button></form>
<p>Source files stay in the existing private WordPress storage. Exact duplicates are rejected; exact matches follow the plugin’s attachment rules. Possible matches require your decision below. Running and walking remain private under their existing access rules.</p>
<section aria-labelledby="pending-title"><h3 id="pending-title">Pending import reviews</h3><?php if(!$entryReviews): ?><p>No pending imports.</p><?php endif; ?>
<?php foreach($entryReviews as$entry):$review=$entry['review']; ?><article class="import-review event-list-card"><h4>Possible matching workout</h4><?php if(is_wp_error($review)): ?><p role="alert"><?php echo esc_html($review->get_error_message()); ?></p><?php else: ?><p><?php echo esc_html($review['source']); ?> source — compare the records before deciding. No attachment has been made for this pending source.</p>
<div class="entry-compare" tabindex="0" role="region" aria-label="Import comparison"><table><thead><tr><th scope="col">Field</th><th scope="col">Existing workout</th><th scope="col">Uploaded source</th></tr></thead><tbody><?php foreach($review['rows']as$label=>$values): ?><tr><th scope="row"><?php echo esc_html($label); ?></th><?php foreach($values as$value): ?><td><?php echo esc_html($value===null||$value===''?'Not recorded':(string)$value); ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
<a class="control" href="<?php echo esc_url('/?workout='.$review['candidate_id']); ?>">View existing workout</a>
<form method="post" action="/?action=workout_upload" class="review-form"><?php foreach(array('token'=>$entry['token'],'nonce'=>wp_create_nonce('standalone_entry_import_'.$entry['token']),'import_id'=>$review['id'],'revision'=>$review['revision'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?>
<label>Location<select name="location_id"><option value="0">Use preserved import location</option><?php foreach($entryLocations as$loc): ?><option value="<?php echo esc_attr($loc['id']); ?>" <?php selected($review['location'],$loc['id']); ?>><?php echo esc_html($loc['name']); ?></option><?php endforeach; ?></select></label><p>Attach combines the source with the existing workout using the plugin’s source-priority rules. Import separately creates another recorded workout. Review failures keep the source pending.</p><div class="plan-actions"><button name="choice" value="attach">Attach to existing workout</button><button name="choice" value="separate">Import as separate workout</button></div></form><?php endif; ?></article><?php endforeach; ?>
<nav class="event-filters" aria-label="Import review pages"><?php if($entryPage>1): ?><a class="control" href="<?php echo esc_url('/?screen=import&review_page='.($entryPage-1)); ?>">Previous reviews</a><?php endif;if($entryPage<$entryPages): ?><a class="control" href="<?php echo esc_url('/?screen=import&review_page='.($entryPage+1)); ?>">Next reviews</a><?php endif; ?></nav></section></section>
